    1  | const response_2 = await openRouter.chat.send({
    2  |   model: 'google/gemini-3-flash-preview',
    3  |   messages,
    4  |   tools,
    5  |   stream: false,
    6  | });
    7  | 
    8  | console.log(response_2.choices[0].message.content);

